from author import *
c=C('向量与空间解析几何')
S(c,'课程导学与十章知识地图',[T('课程定位','先认题型，再写公式与条件'),T('学习方法','每章暂停做题，再核对答案')],[P('这一小时按常见大学高数下的范围，集中练考试里最基本的计算题。先学空间里的点、线和面，再处理多元求导、重积分、曲线曲面积分，最后判断级数。每个新符号都会结合例题说明，不展开定理证明。遇到四秒练习，可以暂停多算一会儿。学校的实际考纲和往年题，仍是最后核对范围的依据。',[1,2],['公式要和适用条件一起记','先独立动手，再看答案'])],[],kind='overview')
S(c,'坐标、向量长度与单位向量',[R('由两点得到向量',r'A=(0,0,0),\ B=(1,2,2),\quad\vec{AB}=(1,2,2)'),R('长度',r'|\mathbf a|=\sqrt{a_1^2+a_2^2+a_3^2}=3'),R('单位化',r'\mathbf e=\frac{\mathbf a}{|\mathbf a|}=\left(\frac13,\frac23,\frac23\right)')],[P('先看空间中的三个坐标轴。点用三个数标位置，向量用三个数表示位移。从A指向B，要用终点坐标减起点坐标。本题A是原点，B是一、二、二，所以得到同样的三个分量。向量长度把三个分量分别平方、相加，再开平方，得到三，不是把分量直接相加。',[1,2],['终点减起点，顺序不能反','长度是平方和开根号'],phase='first',anchor='先看空间中的三个坐标轴'),P('把向量除以自己的长度，就得到同方向、长度为一的单位向量。这里三个分量都除以三。方向导数、投影题经常要求先做这一步，漏除长度，后面的结果就会多出一个倍数。零向量没有确定方向，不能除以零做单位化；题目给出的方向向量必须先确认非零。',[3],['每个分量都除以长度','零向量不能单位化'],phase='unit',anchor='把向量除以自己的长度')],['向量坐标与单位化'],visual=G('vectors3'))
S(c,'点积、夹角与投影',[R('点积得到一个数',r'\mathbf a\cdot\mathbf b=a_1b_1+a_2b_2+a_3b_3'),R('非零向量的夹角',r'\cos\theta=\frac{\mathbf a\cdot\mathbf b}{|\mathbf a|\,|\mathbf b|}'),R('例题',r'\mathbf a=(1,0,1),\ \mathbf b=(0,1,1):\quad\cos\theta=\frac12'),R('投影注意两种量',r'\operatorname{proj}_{\mathbf b}\mathbf a=\frac{\mathbf a\cdot\mathbf b}{|\mathbf b|^2}\mathbf b=\frac12\mathbf b')],[P('点积也叫数量积，计算时对应分量相乘，再把三项加起来，结果是一个数。两个非零向量点积为零，就互相垂直。要求夹角，用点积除以两条向量长度的乘积。例题点积为一，两个长度都是根号二，因此余弦是二分之一，夹角为六十度。',[1,2,3],['点积的结果是标量','判垂直前确认向量非零']),P('投影题要看问的是投影长度，还是投影向量。有向投影长度除以目标向量的长度；投影向量则除以它的长度平方，再乘目标向量。本页第四行问向量，所以是二分之一乘b。不要看到投影二字就套同一个分母，先看最终答案应该是一个数，还是三个分量。',[4],['投影向量还要乘方向向量','标量投影的分母只有一次长度'])],['点积、夹角与投影'])
S(c,'叉积、面积与混合积',[R('叉积仍是向量',r'(1,0,0)\times(0,2,0)=(0,0,2)'),R('面积与体积',r'S=|\mathbf a\times\mathbf b|=2,\quad V=|(\mathbf a\times\mathbf b)\cdot\mathbf c|'),R('取第三条边',r'\mathbf c=(0,0,3)\quad\Longrightarrow\quad V=6')],[P('现在把两条边围成的平行四边形画出来。叉积的方向同时垂直于两条边，长度等于平行四边形面积。本例一条边沿x轴长一，另一条沿y轴长二，叉积沿正z方向长二。若题目问三角形面积，还要把这个面积除以二。交换叉积的先后顺序，方向会反过来。',[1,2],['叉积是向量，点积是数','三角形面积要再除以二'],phase='area',anchor='现在把两条边围成的平行四边形画出来'),P('再沿第三条边把底面拉成立体。叉积再点乘第三条边，得到混合积，取绝对值就是平行六面体体积。第三条边沿z轴长三，因此二乘三等于六。三条向量混合积为零可以判断共面；用来求体积时一定取绝对值，负号只反映取向，不能交负体积。',[3],['混合积为零对应三向量共面','体积取绝对值'],phase='volume',anchor='再沿第三条边把底面拉成立体')],['叉积与混合积'],visual=G('cross3'))
S(c,'平面方程与点到平面的距离',[R('点法式',r'A(x-x_0)+B(y-y_0)+C(z-z_0)=0'),R('给定一点与法向',r'M=(1,0,2),\quad\mathbf n=(1,2,-1)'),R('代入并展开',r'(x-1)+2y-(z-2)=0\quad\Longrightarrow\quad x+2y-z+1=0'),R('原点到本平面的距离',r'd=\frac{|D|}{\sqrt{A^2+B^2+C^2}}=\frac1{\sqrt6}')],[P('写平面方程，最常用的是一个点加一条法向量。法向量垂直于平面，它的三个分量分别放在三个坐标差前面。代入本题的一、零、二和法向量一、二、负一，展开后得到第三行。做完把给定点代回去，左边应该为零，这是很快的符号自查。',[1,2,3],['法向量放在坐标差前','给定点必须满足所得方程']),P('点到一般平面的距离，把点的坐标代入平面左边，取绝对值，再除以法向量长度。本题点是原点，分子只剩常数项一，分母根号六。若点不是原点，分子仍要完整代入，不能只抄常数。平面方程整体乘非零倍数，距离应保持不变，可以用来检查分子分母是否配套。',[4],['分子取绝对值，分母是法向量长度','一般点要完整代入平面左边'])],['平面与点面距离'])
S(c,'空间直线与位置关系',[R('点与方向向量',r'M=(1,0,2),\quad\mathbf s=(1,2,-1)'),R('参数式',r'x=1+t,\qquad y=2t,\qquad z=2-t'),T('常见位置关系','方向向量与法向量点积为零：直线方向平行于平面'),T('方向与法向分开','直线用方向向量；平面用法向量')],[P('写直线时，需要直线经过的一个点，以及它自己的方向向量。把方向向量乘参数t，再加到这个点上，就得到三个参数式。参数式不需要除法，即使某个方向分量为零也能直接用。这种情况下，相应坐标保持常数，不要在对称式中强行写出分母为零的分数。',[1,2],['参数式适合零方向分量','参数为同一个t，不能各取各的']),P('判断位置关系，先分清你手里的向量是谁。两直线方向成比例，说明方向平行；直线方向与平面法向点积为零，说明方向平行于平面，直线可能在面内，也可能与面分离，还要代入点判断。若直线方向与平面法向平行，则直线垂直于平面，别把这两种规则颠倒。',[3,4],['方向平行于面，不等于直线一定在面外','直线方向与法向平行时，线面垂直'])],['直线与位置关系'])
S(c,'球面、柱面与常见二次曲面',[R('球面与圆柱面',r'x^2+y^2+z^2=4,\qquad x^2+y^2=1'),R('旋转抛物面',r'z=x^2+y^2'),R('马鞍面',r'z=x^2-y^2')],[P('先看球面与柱面的差别。球面三个坐标都参与平方和，半径二要在右边写四。圆柱方程没有z，表示高度可以自由变化，沿z方向延伸。读三重积分区域时，经常先认出这些基本形状，再找上下边界；看到某个坐标没出现，要想到它对应方向的自由延伸。',[1],['平方和等于半径平方','缺少一个坐标，常对应柱面延伸'],phase='sphere',anchor='先看球面与柱面的差别'),P('再看两个最常用的曲面。平方和得到向上开的碗形，平方差得到一边上升、一边下降的马鞍形。考试识图先看正负号和截面：固定y为零、再固定x为零，分别得到哪条平面曲线。图形用于帮你选区域、认鞍点，不需要在考场上画得漂亮，但坐标轴和开口方向要标对。',[2,3],['固定一个变量，先看二维截面','平方和与平方差形状不同'],phase='saddle',anchor='再看两个最常用的曲面')],['常见二次曲面'],visual=G('quadrics'))
S(c,'空间几何练习',[R('已知',r'M=(1,1,1),\quad\mathbf n=(1,-1,2)'),T('任务','求过M、法向为n的平面；再求原点到它的距离')],[P('暂停练习：一个平面经过一、一、一，法向量是一、负一、二。先写点法式并展开，再求原点到平面的距离。先在纸上分别圈出点和法向量，避免把三个分量的位置抄反。距离公式的分子要取绝对值，分母要把法向三个分量全部平方后再开根号。',[1,2],['点法式展开后自查给定点','距离公式检查绝对值与平方和'])],['平面与点面距离'],kind='question')
S(c,'空间几何练习答案',[R('点法式',r'(x-1)-(y-1)+2(z-1)=0'),R('展开',r'x-y+2z-2=0'),R('距离',r'd=\frac2{\sqrt6}')],[P('答案是x减y加二z减二等于零。代入一、一、一，确实得到零；三个变量前的系数也与给定法向一致。原点代入后左边是负二，分子取绝对值为二，分母根号六，所以距离二除以根号六。若你写的是整个方程的相反数也正确，但分子和法向系数必须使用同一版方程。',[1,2,3],['方程整体反号仍表示同一个平面','距离二除以根号六'])],['平面与点面距离'],kind='answer')

c=C('多元函数与偏导数')
S(c,'定义域：把限制条件取交集',[R('题目',r'f(x,y)=\sqrt{4-x^2-y^2}+\ln(x-y)'),R('同时满足',r'x^2+y^2\leq4,\qquad x>y'),T('边界检查','圆周可以取；直线x=y不能取')],[P('先画出函数允许取值的平面区域。二元函数有两个自变量，定义域往往是一块区域。根号内要求非负，所以在半径二的圆盘内；对数内部要求严格大于零，所以还要位于x大于y的一侧。两项同时有定义，必须取两个条件的交集，不能把满足任意一个条件的点都收进来。',[1,2],['偶次根号非负；对数内部严格为正','多个条件同时成立，取交集'],phase='domain',anchor='先画出函数允许取值的平面区域'),P('现在检查两类边界能不能留下。圆周使根号恰好为零，可以保留；斜线x等于y会让对数变成零的对数，必须排除。因此圆盘与这个开半平面的公共部分才是答案。写定义域时保留不等号的严格程度，等号能不能取经常就是这类基础题的得分点。',[3],['圆周和对数边界分别判断','画图后仍要写清不等式'],phase='boundary',anchor='现在检查两类边界能不能留下')],['二元函数定义域'],visual=G('domain'))
S(c,'二元极限：不同路径可以否定存在',[R('原点附近',r'f(x,y)=\frac{xy}{x^2+y^2}'),R('沿x轴',r'y=0\quad\Longrightarrow\quad f=0'),R('沿直线y=x',r'y=x\neq0\quad\Longrightarrow\quad f=\frac12')],[P('二元极限要求从所有允许的方向靠近时，结果都一致。先沿横轴走向原点，本题y为零，函数一直为零。接着换成斜线y等于x，约分后一直是二分之一。两条路径给出不同结果，已经足够说明极限不存在，不必再尝试把所有可能的曲线都列出来。',[1,2],['两条路径结果不同，可判极限不存在','路径上的点必须在定义域内'],phase='axis',anchor='先沿横轴走向原点'),P('现在沿斜线再次靠近原点。要记住，这种方法主要用来否定极限；如果两条路径算出相同结果，仍不能断言极限存在，因为还可能有第三条路径不同。考试里多路径题优先试坐标轴和简单直线，若都相同，再观察是否需要试抛物线，或者改用夹逼与估计来证明存在。',[3],['有限条路径相同，不能证明极限存在','先试简单路径，再决定方法'],phase='diagonal',anchor='现在沿斜线再次靠近原点')],['二元极限'],visual=G('paths'))
S(c,'连续与极限存在的常用判断',[R('分母不为零时可直接代入',r'\lim_{(x,y)\to(1,1)}\frac{x+y}{x^2+y^2}=1'),R('估计例题',r'\left|\frac{x^2y}{x^2+y^2}\right|\leq |y|\quad((x,y)\neq(0,0))'),R('极限与补定义',r'\lim_{(x,y)\to(0,0)}\frac{x^2y}{x^2+y^2}=0,\quad f(0,0)=0')],[P('能够直接代入时，就先直接代入。由连续的基本函数经过合法的加减乘除组成的式子，在分母不为零等条件满足的点连续。第一题代入得到一。若代入出现零除以零，再选其他方法，不要因为题目有两个变量，就把所有普通代入题都做成复杂的路径分析。',[1],['先检查代入是否合法','连续点的极限等于函数值']),P('第二题可以用绝对值估计：x平方除以平方和介于零和一之间，因此整个式子的绝对值不超过绝对值y。靠近原点时这个上界趋于零，原式也趋于零。在原点补定义为零以后就连续。与上一页比较，关键是建立对所有靠近方式都有效的估计，而不是只多试几条路径。',[2,3],['统一估计适用于所有路径','连续还要核对该点的函数值'])],['连续与夹逼估计'])
S(c,'偏导数：对谁求导，其余当常数',[R('例题',r'f(x,y)=x^2y+e^y'),R('对x与对y分别求导',r'f_x=2xy,\qquad f_y=x^2+e^y'),R('最后代入点',r'f_x(1,0)=0,\qquad f_y(1,0)=2')],[P('偏导数的计算口令是：对谁求导，其他自变量暂时当常数。对x求导时，y是固定系数，e的y次方也是常数，所以只剩二xy。对y求导时，x平方是固定系数，结果是x平方加e的y次方。先把这两条公式分开写，别在同一遍计算中同时对两个变量求导。',[1,2],['对x求导时，y当常数','对y求导时，x当常数']),P('要求某一点的偏导数，通常先求出通式，再代坐标。本题代入一和零，得到零与二。若提前把x和y都代成数字，原式变成一个常数，再求导就会错误地得到零。遇到分段函数的特殊点，则要回到偏导定义，沿相应坐标方向取一元差商，不能套一条不适用的通式。',[3],['先求导，再代点','分段函数特殊点检查定义'])],['一阶偏导数'])
S(c,'高阶偏导与混合偏导',[R('例题',r'f=x^2y^3'),R('两次对x求导',r'f_x=2xy^3,\qquad f_{xx}=2y^3'),R('先x后y，与先y后x',r'f_{xy}=6xy^2,\qquad f_{yx}=6xy^2'),T('交换条件','相应混合偏导在邻域内连续，是常用的充分条件')],[P('二阶偏导就是继续求一次偏导。下标重复x，表示对x连求两次；先对x再对y，要在第一步的结果上继续对y求导。本题先得到二x乘y三次方，再对y求导，得到六xy平方。建议在草稿里把第一步写出来，减少把指数与系数一起漏掉的错误。',[1,2,3],['沿前一步结果继续求导','混合偏导不要把两次步骤混成一次']),P('本题反过来求，结果也相同，因为多项式足够光滑。常用的交换次序条件，是相应混合偏导在点的邻域连续；不能对所有分段或不光滑函数直接宣布交换合法。遇到抽象函数的二阶求导，还要同时检查链式法则，外层的偏导本身也可能继续随自变量变化。',[4],['光滑条件支持交换顺序','分段函数不能无条件交换混合偏导'])],['高阶与混合偏导'])
S(c,'偏导存在、连续与可微不要混同',[T('常用蕴含','可微 ⇒ 连续；可微 ⇒ 各一阶偏导存在'),T('还可推出','可微必有各一阶偏导；偏导存在却未必连续或可微'),R('反例补定义',r'f=\frac{xy}{x^2+y^2},\quad f(0,0)=0:\quad f_x(0,0)=f_y(0,0)=0'),T('常用充分条件','一阶偏导在邻域存在且在该点连续，可推出该点可微')],[P('选择题经常考这几种关系。可微一定连续，也一定有偏导；反过来，只有两个偏导存在，信息还不够。第三行就是刚才路径极限不存在的例子，在原点补零以后，沿两条坐标轴函数都为零，所以两个偏导都为零，但函数仍不连续，更不可能可微。',[1,2,3],['偏导只检查特定坐标方向','偏导存在不能倒推出可微']),P('实际计算中，最方便的充分条件通常是一阶偏导在邻域存在，并且在目标点连续。多项式以及定义域内的常见光滑复合函数，通常可以据此使用全微分。做判断题时在箭头上标明方向，既不要把充分条件误说成必要条件，也不要把一个反例只能否定的命题扩展到别的命题。',[4],['偏导连续是常用充分条件','检查题目问必要还是充分'])],['可微与连续的关系'])
S(c,'偏导计算练习',[R('题目',r'f=x^2y+\sin y'),R('任务',r'f_x(1,0),\qquad f_y(1,0),\qquad f_{xy}(1,0)')],[P('暂停计算：函数是x平方乘y，再加正弦y。分别求一、零处对x的偏导、对y的偏导，以及先对x再对y的混合偏导。先在每条算式前写清正在对哪个变量求导，保留通式到最后再代点。尤其注意，正弦y对x求导是零，对y求导才是余弦y。',[1,2],['求导对象先写清','三条通式分别写，再代坐标'])],['一阶偏导数','高阶与混合偏导'],kind='question')
S(c,'偏导计算练习答案',[R('一阶通式',r'f_x=2xy,\qquad f_y=x^2+\cos y'),R('混合偏导',r'f_{xy}=2x'),R('点处结果',r'f_x(1,0)=0,\quad f_y(1,0)=2,\quad f_{xy}(1,0)=2')],[P('答案依次是零、二、二。对x求导只处理x平方那一项，得到二xy；对y求导得到x平方加余弦y。混合偏导从二xy继续对y求导，得到二x，再代x为一。若混合偏导算成零，检查是否在求完第一步以后就提前代入了y为零，从而把后续变化错误地抹掉了。',[1,2,3],['结果是零、二、二','高阶求导也要等求完再代点'])],['一阶偏导数','高阶与混合偏导'],kind='answer')
